import 'package:client/styles/styles.dart';
import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// The AllSides Roundtables logo, as vector art.
///
/// The wordmark is drawn in a theme-driven colour while the cube mark keeps
/// its brand colours, which a PNG could not do -- the previous asset baked the
/// wordmark in at #262626, so it disappeared against a dark background. The
/// source SVG lives at media/logo-roundtables.svg; this file embeds it so the
/// fill can be substituted without an async asset load.
class RoundtablesLogo extends StatelessWidget {
  final double height;

  /// Drops the wordmark and renders only the cube, for narrow layouts.
  final bool markOnly;

  const RoundtablesLogo({
    required this.height,
    this.markOnly = false,
    Key? key,
  }) : super(key: key);

  /// Aspect ratios of the two source artworks.
  static const _wordmarkRatio = 652 / 66;
  static const _markRatio = 61 / 66;

  double get _width => height * (markOnly ? _markRatio : _wordmarkRatio);

  @override
  Widget build(BuildContext context) {
    final source = markOnly
        ? _markSvg
        : _wordmarkSvg.replaceAll('{{fg}}', _hex(_wordmarkColor(context)));

    return SvgPicture.string(
      source,
      width: _width,
      height: height,
      fit: BoxFit.contain,
    );
  }

  /// Mirrors the neutral the artwork was drawn with, so the wordmark keeps its
  /// weight relative to the background in either mode.
  Color _wordmarkColor(BuildContext context) =>
      AppNeutralColors.of(context).neutral800;

  static String _hex(Color color) =>
      '#${(color.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';
}

